import { useCallback, useEffect, useMemo, useState } from 'react';
import Modal from '../Modal';
import { DashboardIcon } from '../ui/DashboardIcon';
import { DwesLoadingCenter } from '../ui/DwesLoadingIndicator';
import PanelAssignmentModal from './PanelAssignmentModal';
import type { TechnicianWorkflowSection } from './PanelAssignmentModal';
import { panelWorkflowApi, supervisorApi, usersApi } from '../../services/api';
import WorkflowPlanTab from './workflow/WorkflowPlanTab';
import WorkflowDependenciesTab from './workflow/WorkflowDependenciesTab';
import WorkflowTimeTab from './workflow/WorkflowTimeTab';
import {
  formatTs,
  stageStatusTone,
  type PanelWorkflowRow,
  type WorkflowTabId,
} from './workflow/workflowTypes';

export type { TechnicianWorkflowSection };

export interface PanelWorkflowWorkspaceModalProps {
  onClose: () => void;
  initialSection?: TechnicianWorkflowSection;
  projectCode: string;
  panelId: string;
  projectName: string;
  panelName: string;
  cableCount?: number;
}

const TABS: Array<{ id: WorkflowTabId; label: string }> = [
  { id: 'plan', label: 'Workflow Plan' },
  { id: 'assignments', label: 'Assignments' },
  { id: 'time', label: 'Time & Productivity' },
  { id: 'dependencies', label: 'Dependencies' },
  { id: 'progress', label: 'Actual Progress' },
  { id: 'delays', label: 'Delays & Alerts' },
  { id: 'history', label: 'History' },
];

function messageFrom(error: unknown): string {
  return (error as { response?: { data?: { message?: string } } })?.response?.data?.message
    || 'Workflow workspace could not be loaded.';
}

export default function PanelWorkflowWorkspaceModal({
  onClose,
  initialSection,
  projectCode,
  panelId,
  projectName,
  panelName,
  cableCount = 0,
}: PanelWorkflowWorkspaceModalProps) {
  const [tab, setTab] = useState<WorkflowTabId>(
    initialSection === 'assign' ? 'assignments' : 'plan',
  );
  const [workflow, setWorkflow] = useState<PanelWorkflowRow | null>(null);
  const [history, setHistory] = useState<any[]>([]);
  const [templates, setTemplates] = useState<Array<{ id: number; code: string; name: string }>>([]);
  const [activity, setActivity] = useState<any | null>(null);
  const [technicians, setTechnicians] = useState<any[]>([]);
  const [stageAssignUserId, setStageAssignUserId] = useState('');
  const [stageAssignStageId, setStageAssignStageId] = useState('');
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const resolvedWires = Number(cableCount || activity?.cables_total || 0);
  const scheduleReady = resolvedWires > 0;

  const load = useCallback(async () => {
    setError('');
    try {
      const ensured = await panelWorkflowApi.ensure({
        project_code: projectCode,
        frame_id: panelId,
        panel_name: panelName,
      }) as PanelWorkflowRow;
      const [hist, tpls, act, techs] = await Promise.all([
        panelWorkflowApi.history(ensured.id),
        panelWorkflowApi.listTemplates(),
        supervisorApi.panelActivity(projectCode, panelId).catch(() => null),
        usersApi.technicians().catch(() => []),
      ]);
      setWorkflow(ensured);
      setHistory(Array.isArray(hist) ? hist : []);
      setTemplates(Array.isArray(tpls) ? tpls : []);
      setActivity(act);
      setTechnicians(Array.isArray(techs) ? techs : []);
    } catch (e) {
      setError(messageFrom(e));
    }
  }, [panelId, panelName, projectCode]);

  useEffect(() => {
    let active = true;
    setLoading(true);
    load().finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, [load]);

  const refresh = async () => {
    setBusy(true);
    try {
      await load();
    } finally {
      setBusy(false);
    }
  };

  const wiringCompletion = useMemo(() => {
    if (!activity) return null;
    const pct = Number(activity.progress_pct ?? activity.completion_pct ?? activity.kpi_pct);
    return Number.isFinite(pct) ? pct : null;
  }, [activity]);

  const workflowCompletion = useMemo(() => {
    if (!workflow?.stages?.length) return 0;
    const mandatory = workflow.stages.filter(s => s.enabled && s.mandatory);
    if (!mandatory.length) return 0;
    const done = mandatory.filter(s => {
      const st = String(s.status || '').toUpperCase();
      return st === 'COMPLETED' || st === 'APPROVED';
    }).length;
    return Math.round((done / mandatory.length) * 100);
  }, [workflow]);

  const delayBadge = useMemo(() => {
    if (!workflow) return null;
    const delayedStages = (workflow.stages || []).filter(s =>
      (s.delay_minutes != null && s.delay_minutes > 0)
      || String(s.status || '').toUpperCase() === 'DELAYED'
      || !!s.delay_reason,
    );
    if (delayedStages.length) {
      return { tone: 'warn', label: `${delayedStages.length} stage delay(s)` };
    }
    if (workflow.target_completion_at) {
      const target = new Date(workflow.target_completion_at).getTime();
      if (!Number.isNaN(target) && Date.now() > target && String(workflow.status).toUpperCase() !== 'COMPLETED') {
        return { tone: 'warn', label: 'Past target date' };
      }
    }
    return { tone: 'ok', label: 'On plan' };
  }, [workflow]);

  const techCount = useMemo(() => {
    const wiring = (workflow?.stages || []).find(s => s.stage_key === 'WIRING');
    return Math.max(1, wiring?.assignees?.length || (activity?.technician_id ? 1 : 0) || 1);
  }, [activity, workflow]);

  const run = async (fn: () => Promise<unknown>) => {
    setBusy(true);
    setError('');
    try {
      await fn();
      await load();
    } catch (e) {
      setError(messageFrom(e));
      throw e;
    } finally {
      setBusy(false);
    }
  };

  const assignToStage = async () => {
    if (!stageAssignStageId || !stageAssignUserId) return;
    await run(() => panelWorkflowApi.assignStage(Number(stageAssignStageId), {
      user_id: Number(stageAssignUserId),
      role_hint: 'stage',
    }));
    setStageAssignUserId('');
  };

  return (
    <Modal
      title="Panel Workflow"
      subtitle={`${projectName || projectCode} · ${panelName || panelId}`}
      icon={<DashboardIcon name="projects" size={18} />}
      onClose={onClose}
      size="xl"
      bodyClassName="pw-workspace-body"
      closeOnBackdrop={!busy}
      closeOnEscape={!busy}
      footer={(
        <button type="button" className="btn-secondary" onClick={onClose} disabled={busy}>Close</button>
      )}
    >
      {loading && <DwesLoadingCenter label="Loading panel workflow…" size="sm" />}
      {!loading && error && !workflow && <div className="form-error">{error}</div>}

      {!loading && workflow && (
        <div className="pw-workspace">
          <header className="pw-header" aria-label="Workflow summary">
            <div className="pw-header__grid">
              <div><span>Project</span><strong title={projectName}>{projectName || projectCode}</strong></div>
              <div><span>Project code</span><strong>{projectCode}</strong></div>
              <div><span>Panel</span><strong title={panelName}>{panelName || panelId}</strong></div>
              <div>
                <span>Wiring schedule</span>
                <strong data-tone={scheduleReady ? 'ok' : 'warn'}>
                  {scheduleReady ? `${resolvedWires} wires` : 'Not uploaded'}
                </strong>
              </div>
              <div>
                <span>Workflow status</span>
                <strong className="pw-status-pill" data-tone={stageStatusTone(workflow.status)}>
                  {String(workflow.status || '').replace(/_/g, ' ')}
                </strong>
              </div>
              <div><span>Planned completion</span><strong>{formatTs(workflow.planned_completion_at)}</strong></div>
              <div><span>Forecast completion</span><strong>{formatTs(workflow.forecast_completion_at)}</strong></div>
              <div>
                <span>Delay</span>
                <strong className="pw-status-pill" data-tone={delayBadge?.tone || 'idle'}>
                  {delayBadge?.label || '—'}
                </strong>
              </div>
              <div>
                <span>Wiring completion</span>
                <strong>{wiringCompletion != null ? `${wiringCompletion}%` : '—'}</strong>
              </div>
              <div>
                <span>Overall workflow completion</span>
                <strong>{workflowCompletion}%</strong>
              </div>
            </div>
          </header>

          <nav className="pw-tabs" aria-label="Workflow sections">
            {TABS.map(item => (
              <button
                key={item.id}
                type="button"
                className={`pw-tab${tab === item.id ? ' is-active' : ''}`}
                onClick={() => setTab(item.id)}
              >
                {item.label}
              </button>
            ))}
          </nav>

          {error && <div className="form-error">{error}</div>}

          <div className="pw-tab-panel">
            {tab === 'plan' && (
              <WorkflowPlanTab
                workflow={workflow}
                busy={busy}
                onRefresh={refresh}
                onUpdateStage={async (stageId, body) => {
                  setBusy(true);
                  try {
                    await panelWorkflowApi.updateStage(stageId, body);
                  } finally {
                    setBusy(false);
                  }
                }}
                onAddStage={async body => {
                  setBusy(true);
                  try {
                    await panelWorkflowApi.addStage(workflow.id, body);
                  } finally {
                    setBusy(false);
                  }
                }}
                onApplyTemplate={async templateId => {
                  await run(() => panelWorkflowApi.applyTemplate(workflow.id, {
                    template_id: templateId,
                    mode: 'replace',
                  }));
                }}
                templates={templates}
              />
            )}

            {tab === 'assignments' && (
              <div className="pw-assignments">
                <section className="pw-assignments__wiring">
                  <h3>Panel wiring assignment</h3>
                  <p className="pw-muted">Existing assign path — schedule required before wiring assign.</p>
                  <PanelAssignmentModal
                    embedded
                    onClose={onClose}
                    projectCode={projectCode}
                    panelId={panelId}
                    projectName={projectName}
                    panelName={panelName}
                    cableCount={resolvedWires}
                    onAssigned={() => { void refresh(); }}
                  />
                </section>
                <section className="pw-assignments__stages">
                  <h3>Stage-scoped assignees</h3>
                  <p className="pw-muted">Assign technicians to wiring, testing, rework, packing, or other stages.</p>
                  <div className="pw-form-grid pw-form-grid--compact">
                    <label className="pw-field">
                      <span>Stage</span>
                      <select
                        value={stageAssignStageId}
                        onChange={e => setStageAssignStageId(e.target.value)}
                        disabled={busy}
                      >
                        <option value="">Select stage…</option>
                        {(workflow.stages || []).filter(s => s.enabled).map(s => (
                          <option key={s.id} value={s.id}>{s.name}</option>
                        ))}
                      </select>
                    </label>
                    <label className="pw-field">
                      <span>Technician</span>
                      <select
                        value={stageAssignUserId}
                        onChange={e => setStageAssignUserId(e.target.value)}
                        disabled={busy}
                      >
                        <option value="">Select technician…</option>
                        {technicians.map((t: any) => (
                          <option key={t.id} value={t.id}>
                            {t.full_name || t.username || `Tech #${t.id}`}
                          </option>
                        ))}
                      </select>
                    </label>
                    <div className="pw-inline">
                      <button
                        type="button"
                        className="btn-primary"
                        disabled={busy || !stageAssignStageId || !stageAssignUserId}
                        onClick={() => { void assignToStage(); }}
                      >
                        Assign to stage
                      </button>
                    </div>
                  </div>
                  <ul className="pw-assignee-list">
                    {(workflow.stages || []).flatMap(stage =>
                      (stage.assignees || []).map(a => (
                        <li key={a.id}>
                          <span>
                            <strong>{stage.name}</strong>
                            {' · '}
                            {technicians.find((t: any) => t.id === a.user_id)?.full_name
                              || technicians.find((t: any) => t.id === a.user_id)?.username
                              || `User #${a.user_id}`}
                          </span>
                          <button
                            type="button"
                            className="btn-ghost"
                            disabled={busy}
                            onClick={() => run(() => panelWorkflowApi.removeAssignee(a.id))}
                          >
                            Remove
                          </button>
                        </li>
                      )),
                    )}
                    {(workflow.stages || []).every(s => !(s.assignees || []).length) && (
                      <li className="pw-empty">No stage assignees yet.</li>
                    )}
                  </ul>
                </section>
              </div>
            )}

            {tab === 'time' && (
              <WorkflowTimeTab
                projectCode={projectCode}
                frameId={panelId}
                totalWires={resolvedWires}
                technicianCount={techCount}
                efficiencyFactor={workflow.efficiency_factor != null ? Number(workflow.efficiency_factor) : 1}
                busy={busy}
              />
            )}

            {tab === 'dependencies' && (
              <WorkflowDependenciesTab
                workflow={workflow}
                busy={busy}
                onRefresh={refresh}
                onAddDependency={async body => {
                  setBusy(true);
                  try {
                    await panelWorkflowApi.addDependency(workflow.id, body);
                  } finally {
                    setBusy(false);
                  }
                }}
                onRemoveDependency={async depId => {
                  setBusy(true);
                  try {
                    await panelWorkflowApi.removeDependency(depId);
                  } finally {
                    setBusy(false);
                  }
                }}
              />
            )}

            {tab === 'progress' && (
              <div className="pw-progress">
                <h3>Actual wiring snapshot</h3>
                <p className="pw-muted">Read-only from existing technician execution data. Stage actuals fill in Phase W3.</p>
                <div className="pw-kpi-grid">
                  <div><span>Technician</span><strong>{activity?.technician_name || activity?.technician || '—'}</strong></div>
                  <div><span>Assignment status</span><strong>{activity?.status || '—'}</strong></div>
                  <div><span>Wires completed</span><strong>{activity?.cables_completed ?? '—'}</strong></div>
                  <div><span>Remaining</span><strong>{activity?.cables_remaining ?? '—'}</strong></div>
                  <div><span>Wiring progress</span><strong>{wiringCompletion != null ? `${wiringCompletion}%` : '—'}</strong></div>
                  <div><span>Pause reason</span><strong>{activity?.pause_reason || '—'}</strong></div>
                  <div><span>Active seconds</span><strong>{activity?.active_seconds ?? '—'}</strong></div>
                  <div><span>Overall workflow</span><strong>{workflowCompletion}%</strong></div>
                </div>
                <table className="pw-table">
                  <thead>
                    <tr>
                      <th>Stage</th>
                      <th>Status</th>
                      <th>Progress</th>
                      <th>Actual start</th>
                      <th>Actual finish</th>
                    </tr>
                  </thead>
                  <tbody>
                    {(workflow.stages || []).map(s => (
                      <tr key={s.id}>
                        <td>{s.name}</td>
                        <td>{String(s.status || '').replace(/_/g, ' ')}</td>
                        <td>{s.progress_pct || 0}%</td>
                        <td>{formatTs(s.actual_start_at)}</td>
                        <td>{formatTs(s.actual_finish_at)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}

            {tab === 'delays' && (
              <div className="pw-delays">
                <div className="pw-banner-info" role="note">
                  Alerts are planning/management only — they never punish or modify technician records. Full alert engine arrives in Phase W4.
                </div>
                <ul className="pw-delay-list">
                  {(workflow.stages || [])
                    .filter(s => s.delay_reason || (s.delay_minutes != null && s.delay_minutes > 0) || String(s.status).toUpperCase() === 'DELAYED')
                    .map(s => (
                      <li key={s.id}>
                        <strong>{s.name}</strong>
                        <span className="pw-status-pill" data-tone="warn">
                          {s.delay_minutes != null ? `${s.delay_minutes} min` : 'DELAYED'}
                        </span>
                        <p>{s.delay_reason || 'No reason recorded yet.'}</p>
                      </li>
                    ))}
                  {(workflow.stages || []).every(s =>
                    !s.delay_reason && !(s.delay_minutes != null && s.delay_minutes > 0)
                    && String(s.status).toUpperCase() !== 'DELAYED',
                  ) && (
                    <li className="pw-empty">No stage delays recorded. Alert rules (wire/hour/day/dependency) arrive in W4.</li>
                  )}
                </ul>
              </div>
            )}

            {tab === 'history' && (
              <div className="pw-history">
                <ul className="pw-history-list">
                  {history.length === 0 && <li className="pw-empty">No workflow events yet.</li>}
                  {history.map((row: any) => (
                    <li key={row.id}>
                      <div className="pw-history-list__head">
                        <strong>{String(row.event_type || '').replace(/_/g, ' ')}</strong>
                        <span>{formatTs(row.created_at)}</span>
                      </div>
                      <div className="pw-history-list__meta">
                        {row.user_role || 'system'}{row.reason ? ` · ${row.reason}` : ''}
                      </div>
                      {(row.previous_value || row.new_value) && (
                        <pre className="pw-history-list__json">
                          {row.previous_value ? `prev: ${row.previous_value}\n` : ''}
                          {row.new_value ? `new: ${row.new_value}` : ''}
                        </pre>
                      )}
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        </div>
      )}
    </Modal>
  );
}

import { useState } from 'react';
import { ChevronDown, ChevronRight, Plus } from '../../ui/icons';
import {
  formatDurationMinutes,
  formatTs,
  stageStatusTone,
  type PanelWorkflowRow,
  type WorkflowStageRow,
} from './workflowTypes';

type Props = {
  workflow: PanelWorkflowRow;
  busy: boolean;
  onRefresh: () => Promise<void>;
  onUpdateStage: (stageId: number, body: Record<string, unknown>) => Promise<void>;
  onAddStage: (body: Record<string, unknown>) => Promise<void>;
  onApplyTemplate: (templateId: number) => Promise<void>;
  templates: Array<{ id: number; code: string; name: string }>;
};

export default function WorkflowPlanTab({
  workflow,
  busy,
  onRefresh,
  onUpdateStage,
  onAddStage,
  onApplyTemplate,
  templates,
}: Props) {
  const [expandedId, setExpandedId] = useState<number | null>(null);
  const [draft, setDraft] = useState<Partial<WorkflowStageRow> | null>(null);
  const [customName, setCustomName] = useState('');
  const [templateId, setTemplateId] = useState('');
  const [error, setError] = useState('');
  const stages = [...(workflow.stages || [])].sort((a, b) => a.sequence - b.sequence);
  const depLabel = (stage: WorkflowStageRow) => {
    const deps = (workflow.stage_deps || []).filter(d => d.stage_id === stage.id);
    if (!deps.length) return 'None';
    return deps.map(d => {
      const prereq = stages.find(s => s.id === d.prerequisite_stage_id);
      return prereq?.name || `#${d.prerequisite_stage_id}`;
    }).join(', ');
  };

  const openEdit = (stage: WorkflowStageRow) => {
    setExpandedId(stage.id);
    setDraft({ ...stage });
    setError('');
  };

  const saveDraft = async () => {
    if (!draft?.id) return;
    setError('');
    try {
      await onUpdateStage(draft.id, {
        name: draft.name,
        enabled: draft.enabled,
        mandatory: draft.mandatory,
        requires_approval: draft.requires_approval,
        planned_duration_minutes: draft.planned_duration_minutes,
        planned_start_at: draft.planned_start_at,
        planned_finish_at: draft.planned_finish_at,
        instructions: draft.instructions,
        remarks: draft.remarks,
        priority: draft.priority,
        sequence: draft.sequence,
      });
      await onRefresh();
    } catch (e: any) {
      setError(e?.response?.data?.message || 'Could not save stage.');
    }
  };

  const move = async (stage: WorkflowStageRow, dir: -1 | 1) => {
    const idx = stages.findIndex(s => s.id === stage.id);
    const swap = stages[idx + dir];
    if (!swap) return;
    const tempSeq = Math.max(...stages.map(s => s.sequence), 0) + 1000;
    try {
      // Three-step swap avoids unique (workflow_id, sequence) conflicts.
      await onUpdateStage(stage.id, { sequence: tempSeq });
      await onUpdateStage(swap.id, { sequence: stage.sequence });
      await onUpdateStage(stage.id, { sequence: swap.sequence });
      await onRefresh();
    } catch (e: any) {
      setError(e?.response?.data?.message || 'Could not reorder stages.');
    }
  };

  const addCustom = async () => {
    const name = customName.trim();
    if (!name) return;
    const key = `CUSTOM_${name.toUpperCase().replace(/[^A-Z0-9]+/g, '_').slice(0, 40)}`;
    try {
      await onAddStage({ stage_key: key, name, mandatory: false });
      setCustomName('');
      await onRefresh();
    } catch (e: any) {
      setError(e?.response?.data?.message || 'Could not add stage.');
    }
  };

  return (
    <div className="pw-plan">
      <div className="pw-plan__toolbar">
        <label className="pw-field">
          <span>Apply template (copies into this panel)</span>
          <div className="pw-inline">
            <select
              value={templateId}
              onChange={e => setTemplateId(e.target.value)}
              disabled={busy || !templates.length}
            >
              <option value="">Select template…</option>
              {templates.map(t => (
                <option key={t.id} value={t.id}>{t.name} ({t.code})</option>
              ))}
            </select>
            <button
              type="button"
              className="btn-secondary"
              disabled={busy || !templateId}
              onClick={() => onApplyTemplate(Number(templateId))}
            >
              Apply
            </button>
          </div>
        </label>
        <label className="pw-field">
          <span>Add custom stage</span>
          <div className="pw-inline">
            <input
              value={customName}
              onChange={e => setCustomName(e.target.value)}
              placeholder="Stage name"
              disabled={busy}
            />
            <button type="button" className="btn-secondary" disabled={busy || !customName.trim()} onClick={addCustom}>
              <Plus size={16} /> Add
            </button>
          </div>
        </label>
      </div>

      <p className="pw-planning-note">Planning value — confirm duration before use. Stage start/complete controls arrive in Phase W3.</p>
      {error && <div className="form-error">{error}</div>}

      <ol className="pw-timeline">
        {stages.map((stage, index) => {
          const open = expandedId === stage.id;
          return (
            <li key={stage.id} className={`pw-stage-card${!stage.enabled ? ' is-disabled' : ''}`}>
              <div className="pw-stage-card__main">
                <button
                  type="button"
                  className="pw-stage-card__expand"
                  aria-expanded={open}
                  onClick={() => (open ? setExpandedId(null) : openEdit(stage))}
                >
                  {open ? <ChevronDown size={18} /> : <ChevronRight size={18} />}
                  <span className="pw-stage-card__seq">{stage.sequence}</span>
                  <strong>{stage.name}</strong>
                </button>
                <span className={`pw-status-pill`} data-tone={stageStatusTone(stage.status)}>
                  {String(stage.status || 'NOT_PLANNED').replace(/_/g, ' ')}
                </span>
                <span className="pw-stage-card__meta" title="Planned duration">
                  {formatDurationMinutes(stage.planned_duration_minutes)}
                </span>
                <span className="pw-stage-card__meta" title="Dependency">← {depLabel(stage)}</span>
                <div className="pw-stage-card__progress">
                  <progress value={stage.progress_pct || 0} max={100} aria-label={`${stage.name} progress`} />
                  <span>{stage.progress_pct || 0}%</span>
                </div>
                <div className="pw-stage-card__actions">
                  <button type="button" className="btn-ghost" disabled={busy || index === 0} onClick={() => move(stage, -1)}>Up</button>
                  <button type="button" className="btn-ghost" disabled={busy || index === stages.length - 1} onClick={() => move(stage, 1)}>Down</button>
                  <button type="button" className="btn-secondary" disabled={busy} onClick={() => openEdit(stage)}>Edit</button>
                </div>
              </div>

              {open && draft && draft.id === stage.id && (
                <div className="pw-stage-card__detail">
                  <div className="pw-form-grid">
                    <label className="pw-field">
                      <span>Name</span>
                      <input value={draft.name || ''} onChange={e => setDraft({ ...draft, name: e.target.value })} />
                    </label>
                    <label className="pw-field">
                      <span>Priority</span>
                      <input value={draft.priority || ''} onChange={e => setDraft({ ...draft, priority: e.target.value })} placeholder="Normal" />
                    </label>
                    <label className="pw-field">
                      <span>Planned duration (minutes)</span>
                      <input
                        type="number"
                        min={0}
                        value={draft.planned_duration_minutes ?? ''}
                        onChange={e => setDraft({
                          ...draft,
                          planned_duration_minutes: e.target.value === '' ? null : Number(e.target.value),
                        })}
                        placeholder="Confirm before use"
                      />
                    </label>
                    <label className="pw-field">
                      <span>Sequence</span>
                      <input
                        type="number"
                        min={1}
                        value={draft.sequence ?? stage.sequence}
                        onChange={e => setDraft({ ...draft, sequence: Number(e.target.value) })}
                      />
                    </label>
                    <label className="pw-field">
                      <span>Planned start</span>
                      <input
                        type="datetime-local"
                        value={toLocalInput(draft.planned_start_at)}
                        onChange={e => setDraft({ ...draft, planned_start_at: fromLocalInput(e.target.value) })}
                      />
                    </label>
                    <label className="pw-field">
                      <span>Planned finish</span>
                      <input
                        type="datetime-local"
                        value={toLocalInput(draft.planned_finish_at)}
                        onChange={e => setDraft({ ...draft, planned_finish_at: fromLocalInput(e.target.value) })}
                      />
                    </label>
                    <label className="pw-check">
                      <input
                        type="checkbox"
                        checked={!!draft.enabled}
                        onChange={e => setDraft({ ...draft, enabled: e.target.checked })}
                      />
                      Enabled
                    </label>
                    <label className="pw-check">
                      <input
                        type="checkbox"
                        checked={!!draft.mandatory}
                        onChange={e => setDraft({ ...draft, mandatory: e.target.checked })}
                      />
                      Mandatory
                    </label>
                    <label className="pw-check">
                      <input
                        type="checkbox"
                        checked={!!draft.requires_approval}
                        onChange={e => setDraft({ ...draft, requires_approval: e.target.checked })}
                      />
                      Requires approval
                    </label>
                    <label className="pw-field pw-field--full">
                      <span>Instructions</span>
                      <textarea
                        rows={2}
                        value={draft.instructions || ''}
                        onChange={e => setDraft({ ...draft, instructions: e.target.value })}
                      />
                    </label>
                    <label className="pw-field pw-field--full">
                      <span>Remarks</span>
                      <textarea
                        rows={2}
                        value={draft.remarks || ''}
                        onChange={e => setDraft({ ...draft, remarks: e.target.value })}
                      />
                    </label>
                  </div>
                  <div className="pw-stage-card__detail-meta">
                    <span>Actual start: {formatTs(stage.actual_start_at)}</span>
                    <span>Actual finish: {formatTs(stage.actual_finish_at)}</span>
                    <span>Assignees: {(stage.assignees || []).length || 'None'}</span>
                  </div>
                  <div className="pw-inline">
                    <button type="button" className="btn-primary" disabled={busy} onClick={saveDraft}>Save stage</button>
                    <button type="button" className="btn-secondary" onClick={() => setExpandedId(null)}>Collapse</button>
                  </div>
                </div>
              )}
            </li>
          );
        })}
      </ol>
    </div>
  );
}

function toLocalInput(value: string | null | undefined): string {
  if (!value) return '';
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return '';
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

function fromLocalInput(value: string): string | null {
  if (!value) return null;
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
}

import { useEffect, useState } from 'react';
import { panelWorkflowApi } from '../../../services/api';
import type { ProductivityDefaults, WiringEstimate } from './workflowTypes';

type Props = {
  projectCode: string;
  frameId: string;
  totalWires: number;
  technicianCount: number;
  efficiencyFactor: number | null;
  busy: boolean;
};

const FIELD_META: Array<{ key: keyof ProductivityDefaults; label: string; hint?: string }> = [
  { key: 'regular_hours_per_day', label: 'Regular working hours / day', hint: 'Default 10' },
  { key: 'productive_hours_per_shift', label: 'Productive hours / shift', hint: 'Default 10' },
  { key: 'target_wires_per_day', label: 'Target wires / day', hint: 'Default 220' },
  { key: 'target_wires_per_hour', label: 'Target wires / hour', hint: 'Default 22' },
  { key: 'standard_minutes_per_wire', label: 'Standard minutes / wire' },
  { key: 'wire_delay_warning_minutes', label: 'Wire-delay warning (minutes)', hint: 'Default 15' },
  { key: 'break_duration_minutes', label: 'Short break duration (minutes)' },
  { key: 'lunch_duration_minutes', label: 'Lunch duration (minutes)' },
  { key: 'allowed_overtime_minutes', label: 'Allowed overtime (minutes)' },
];

export default function WorkflowTimeTab({
  projectCode,
  frameId,
  totalWires,
  technicianCount,
  efficiencyFactor,
  busy,
}: Props) {
  const [defaults, setDefaults] = useState<ProductivityDefaults | null>(null);
  const [estimate, setEstimate] = useState<WiringEstimate | null>(null);
  const [techCount, setTechCount] = useState(technicianCount);
  const [efficiency, setEfficiency] = useState(efficiencyFactor ?? 1);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [saved, setSaved] = useState(false);

  const load = async () => {
    setError('');
    try {
      const [d, e] = await Promise.all([
        panelWorkflowApi.productivityDefaults(projectCode) as Promise<ProductivityDefaults>,
        panelWorkflowApi.estimate({
          project_code: projectCode,
          frame_id: frameId,
          total_wires: totalWires,
          technician_count: Math.max(1, techCount),
          efficiency_factor: efficiency,
        }) as Promise<WiringEstimate>,
      ]);
      setDefaults(d);
      setEstimate(e);
    } catch (err: any) {
      setError(err?.response?.data?.message || 'Could not load productivity settings.');
    }
  };

  useEffect(() => {
    void load();
    // eslint-disable-next-line react-hooks/exhaustive-deps -- reload when panel wire/tech context changes
  }, [projectCode, frameId, totalWires]);

  useEffect(() => {
    setTechCount(technicianCount);
  }, [technicianCount]);

  const refreshEstimate = async () => {
    try {
      const e = await panelWorkflowApi.estimate({
        project_code: projectCode,
        frame_id: frameId,
        total_wires: totalWires,
        technician_count: Math.max(1, techCount),
        efficiency_factor: efficiency,
        target_wires_per_hour: defaults?.target_wires_per_hour,
        productive_hours_per_day: defaults?.productive_hours_per_shift,
      }) as WiringEstimate;
      setEstimate(e);
    } catch (err: any) {
      setError(err?.response?.data?.message || 'Could not recalculate estimate.');
    }
  };

  const saveDefaults = async () => {
    if (!defaults) return;
    setSaving(true);
    setSaved(false);
    setError('');
    try {
      const next = await panelWorkflowApi.putProductivityDefaults({
        project_code: projectCode,
        regular_hours_per_day: defaults.regular_hours_per_day,
        productive_hours_per_shift: defaults.productive_hours_per_shift,
        target_wires_per_day: defaults.target_wires_per_day,
        target_wires_per_hour: defaults.target_wires_per_hour,
        standard_minutes_per_wire: defaults.standard_minutes_per_wire,
        wire_delay_warning_minutes: defaults.wire_delay_warning_minutes,
        break_duration_minutes: defaults.break_duration_minutes,
        lunch_duration_minutes: defaults.lunch_duration_minutes,
        allowed_overtime_minutes: defaults.allowed_overtime_minutes,
      }) as ProductivityDefaults;
      setDefaults(next);
      setSaved(true);
      await refreshEstimate();
    } catch (err: any) {
      setError(err?.response?.data?.message || 'Could not save planning values.');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="pw-time">
      <div className="pw-banner-info" role="note">
        Configurable planning values — not permanent business rules. Estimate never overwrites actual wiring data.
      </div>

      <section className="pw-estimate-card" aria-label="Wiring time estimate">
        <h3>Automatic wiring-time estimate</h3>
        <div className="pw-kpi-grid">
          <div><span>Total wires</span><strong>{totalWires}</strong></div>
          <div><span>Target wires/hour</span><strong>{estimate?.target_wires_per_hour ?? '—'}</strong></div>
          <div>
            <span>Planned technicians</span>
            <input
              type="number"
              min={1}
              value={techCount}
              onChange={e => setTechCount(Math.max(1, Number(e.target.value) || 1))}
              disabled={busy}
            />
          </div>
          <div>
            <span>Efficiency factor</span>
            <input
              type="number"
              min={0.1}
              step={0.05}
              value={efficiency}
              onChange={e => setEfficiency(Number(e.target.value) || 1)}
              disabled={busy}
            />
          </div>
          <div><span>Estimated hours</span><strong>{estimate?.estimated_hours ?? '—'}</strong></div>
          <div><span>Estimated working days</span><strong>{estimate?.estimated_working_days ?? '—'}</strong></div>
        </div>
        <div className="pw-inline">
          <button type="button" className="btn-secondary" disabled={busy} onClick={refreshEstimate}>Recalculate</button>
        </div>
        {estimate?.formula && <p className="pw-muted">{estimate.formula}</p>}
        <div className="pw-vs-grid">
          <div>
            <h4>Estimated (planning)</h4>
            <p>{estimate?.estimated_hours ?? '—'} hours / {estimate?.estimated_working_days ?? '—'} days</p>
          </div>
          <div>
            <h4>Actual (execution)</h4>
            <p>Available in Phase W4 from wiring activity — not overwritten here.</p>
          </div>
        </div>
      </section>

      <section className="pw-defaults" aria-label="Productivity defaults">
        <h3>Supervisor productivity configuration</h3>
        <div className="pw-form-grid">
          {FIELD_META.map(field => (
            <label key={field.key} className="pw-field">
              <span>{field.label}{field.hint ? ` · ${field.hint}` : ''}</span>
              <input
                type="number"
                disabled={!defaults || busy || saving}
                value={defaults?.[field.key] == null ? '' : Number(defaults[field.key])}
                onChange={e => {
                  if (!defaults) return;
                  const raw = e.target.value;
                  setDefaults({
                    ...defaults,
                    [field.key]: raw === '' ? null : Number(raw),
                  } as ProductivityDefaults);
                }}
              />
            </label>
          ))}
        </div>
        <div className="pw-inline">
          <button type="button" className="btn-primary" disabled={!defaults || busy || saving} onClick={saveDefaults}>
            {saving ? 'Saving…' : 'Save planning values'}
          </button>
          {saved && <span className="pw-ok">Saved for this project scope.</span>}
        </div>
      </section>

      {error && <div className="form-error">{error}</div>}
    </div>
  );
}

import { useMemo, useState } from 'react';
import type { PanelWorkflowRow } from './workflowTypes';

type Props = {
  workflow: PanelWorkflowRow;
  busy: boolean;
  onRefresh: () => Promise<void>;
  onAddDependency: (body: { stage_id: number; prerequisite_stage_id: number }) => Promise<void>;
  onRemoveDependency: (depId: number) => Promise<void>;
};

export default function WorkflowDependenciesTab({
  workflow,
  busy,
  onRefresh,
  onAddDependency,
  onRemoveDependency,
}: Props) {
  const stages = useMemo(
    () => [...(workflow.stages || [])].filter(s => s.enabled).sort((a, b) => a.sequence - b.sequence),
    [workflow.stages],
  );
  const deps = workflow.stage_deps || [];
  const [stageId, setStageId] = useState('');
  const [prereqId, setPrereqId] = useState('');
  const [error, setError] = useState('');

  const nameOf = (id: number) => stages.find(s => s.id === id)?.name || `#${id}`;

  const add = async () => {
    if (!stageId || !prereqId) return;
    setError('');
    try {
      await onAddDependency({
        stage_id: Number(stageId),
        prerequisite_stage_id: Number(prereqId),
      });
      setStageId('');
      setPrereqId('');
      await onRefresh();
    } catch (e: any) {
      setError(e?.response?.data?.message || 'Could not add dependency.');
    }
  };

  return (
    <div className="pw-deps">
      <p className="pw-planning-note">
        Recommended flow: Wiring → AC/DC Testing → HV Testing → HV Rework → FAT → Packing Readiness → Packing → Dispatch.
        Enforcement of start blockers is Phase W3.
      </p>

      <div className="pw-dep-diagram" aria-label="Dependency diagram">
        {stages.map((stage, i) => (
          <div key={stage.id} className="pw-dep-node-wrap">
            {i > 0 && <span className="pw-dep-arrow" aria-hidden>→</span>}
            <div className="pw-dep-node">
              <span className="pw-dep-node__seq">{stage.sequence}</span>
              <strong>{stage.name}</strong>
            </div>
          </div>
        ))}
      </div>

      <ul className="pw-dep-list">
        {deps.length === 0 && <li className="pw-empty">No explicit dependencies recorded.</li>}
        {deps.map(dep => (
          <li key={dep.id}>
            <span><strong>{nameOf(dep.prerequisite_stage_id)}</strong> → <strong>{nameOf(dep.stage_id)}</strong></span>
            <button
              type="button"
              className="btn-ghost"
              disabled={busy}
              onClick={async () => {
                await onRemoveDependency(dep.id);
                await onRefresh();
              }}
            >
              Remove
            </button>
          </li>
        ))}
      </ul>

      <div className="pw-form-grid pw-form-grid--compact">
        <label className="pw-field">
          <span>Prerequisite</span>
          <select value={prereqId} onChange={e => setPrereqId(e.target.value)} disabled={busy}>
            <option value="">Select…</option>
            {stages.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
          </select>
        </label>
        <label className="pw-field">
          <span>Dependent stage</span>
          <select value={stageId} onChange={e => setStageId(e.target.value)} disabled={busy}>
            <option value="">Select…</option>
            {stages.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
          </select>
        </label>
        <div className="pw-inline">
          <button type="button" className="btn-primary" disabled={busy || !stageId || !prereqId} onClick={add}>
            Add dependency
          </button>
        </div>
      </div>
      {error && <div className="form-error">{error}</div>}
    </div>
  );
}

import {
