  @Roles(...WRITE_ROLES)
  update(@Param('id', ParseIntPipe) id: number, @Body() body: any, @CurrentUser() user: User) {
    return this.svc.updateWorkflow(id, body || {}, user);
  }

  @Delete(':id')
  @Roles(...WRITE_ROLES)
  remove(@Param('id', ParseIntPipe) id: number, @CurrentUser() user: User) {
